package com.onlineassessment.security; import com.onlineassessment.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService { private final UserRepository users; public UserDetails loadUserByUsername(String email){var u=users.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("User not found")); return User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).disabled(!u.isActive()).build();} }
